/* Starter words per language, most useful first. Never change a lemma here once shipped: a word's id comes from it.
   Example sentences use a small markup (see sentence() in src/lib/tokens.ts):
   tokens separated by spaces, fields by "|": surface|lemma|gloss|reading. "=" as lemma means "same as surface".
   A token with no "|" is punctuation. */
import type { Lang } from "../types";

export interface StarterWord {
  lemma: string;
  reading?: string;
  /** Greek, Russian: worked out from the lemma; Polish / Portuguese: the lemma */
  translit?: string;
  gloss: string;
  pos: string;
  ex?: [spec: string, translation: string];
  note?: string;
  root?: string;
  hebrew?: string;
}

